function MultiStepForm() {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    // Step 1
    firstName: '',
    lastName: '',
    // Step 2
    email: '',
    phone: '',
    // Step 3
    address: '',
    city: ''
  });

  const nextStep = () => setStep(step + 1);
  const prevStep = () => setStep(step - 1);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = () => {
    console.log('Submit:', formData);
  };

  switch (step) {
    case 1: return <PersonalInfo data={formData} onChange={handleChange} onNext={nextStep} />;
    case 2: return <ContactInfo data={formData} onChange={handleChange} onNext={nextStep} onBack={prevStep} />;
    case 3: return <AddressInfo data={formData} onChange={handleChange} onBack={prevStep} onSubmit={handleSubmit} />;
  }
}

function ProgressBar({ currentStep, totalSteps }) {
  const progress = (currentStep / totalSteps) * 100;

  return (
    <div className="progress-container">
      <div className="progress-bar" style={{ width: `${progress}%` }} />
      <span>Step {currentStep} of {totalSteps}</span>
    </div>
  );
}
